import{_ as t,c as a,G as o,J as e,C as s,a4 as r,V as n,b as l,B as i,D as g}from"./chunks/framework.DULpp8DO.js";const u=JSON.parse('{"title":"Agent 评测（Evals）实战：如何科学衡量一个智能体","description":"从统计原理到工程落地，系统讲解如何构建 Agent 评测体系：评测的三个层次、eval set 构建、LLM-as-judge 偏差、pass@k 与回归防御。","frontmatter":{"title":"Agent 评测（Evals）实战：如何科学衡量一个智能体","date":"2026-09-20T00:00:00.000Z","categories":["技术分享"],"tags":["Agent 评测","Evals","Benchmark","LLM","工程"],"description":"从统计原理到工程落地，系统讲解如何构建 Agent 评测体系：评测的三个层次、eval set 构建、LLM-as-judge 偏差、pass@k 与回归防御。","articleGPT":"本文的核心命题来自 Manus 团队的实践：对非确定性的 LLM 输出，\\"感觉变好了\\"不是证据，只有统计手段才配下结论。文章先把评测拆成三个层次——单元级（单工具调用正确性）、任务级（端到端成功率）、系统级（成本/延迟/安全回归），然后给出构建自有 eval set 的方法论：从真实失败案例出发、至少 10-20 个用例才能看到信号、警惕小样本上宣称提升的统计陷阱。接着深入 LLM-as-judge 的三大偏差（位置偏差、长度偏差、自我偏好）及其缓解手段，解释 pass@k 与 pass^k 的本质区别与多轮重复实验的做法，强调\\"模型/提示/工具任何变更都跑全量 eval\\"的回归纪律，并讨论评测环境隔离与数据污染问题。最后给出 promptfoo、LangSmith 与自建 harness 的工具选型建议。读完即可为团队搭建一套可信的 Agent 评测流水线。","cover":"https://lsky.rz15.cn/i/2026/11/19/6afed4306b090.png","top":null,"share":true,"delete":false,"head":[["link",{"rel":"canonical","href":"https://ruo.ge/posts/2026-09/20260920"}]]},"headers":[],"relativePath":"posts/2026-09/20260920.md","filePath":"posts/2026-09/20260920.md","lastUpdated":1795486093000}');const p=t({name:"posts/2026-09/20260920.md"},[["render",function(t,u,p,h,d,q){const E=n("Mermaid");return l(),a("div",null,[u[1]||(u[1]=o('<h1 id="agent-评测-evals-实战-如何科学衡量一个智能体" tabindex="-1">Agent 评测（Evals）实战：如何科学衡量一个智能体 <a class="header-anchor" href="#agent-评测-evals-实战-如何科学衡量一个智能体" aria-label="Permalink to &quot;Agent 评测（Evals）实战：如何科学衡量一个智能体&quot;">​</a></h1><h2 id="感觉变好了-为什么不可靠" tabindex="-1">&quot;感觉变好了&quot;为什么不可靠 <a class="header-anchor" href="#感觉变好了-为什么不可靠" aria-label="Permalink to &quot;&quot;感觉变好了&quot;为什么不可靠&quot;">​</a></h2><p>改了一版 system prompt，翻了几十个对话记录，感觉 Agent 回答更靠谱了——这是几乎所有 Agent 团队都经历过的决策时刻。Manus 团队在一篇广为流传的博客里把这个现象点破了：<strong>LLM 输出是非确定性的，人类对非确定性系统的直觉判断天然失准</strong>，你不看数据，你的大脑会自动挑选支持你直觉的样本。</p><p>这不是态度问题，是数学问题。假设某任务的真实成功率为 60%，你抽查 10 个对话看到 7 次成功，这和 60% 的假设完全相容（二项分布下 P(X&gt;=7) 约 0.18）；你今天运气好看到 7 成功、昨天运气差看到 4 成功，两天的&quot;感受&quot;能差出 30 个百分点，而背后什么都没变。反过来，如果你在 5 个用例上从 3 成变成 4 成，就宣称&quot;提升 20%&quot;，这几乎必然是噪声。</p><p>结论只有一个：<strong>Agent 的每次能力判断都必须建立在足够样本量的重复实验上</strong>。评测（evals）不是锦上添花的工程实践，而是 Agent 开发的方向盘——没有 evals，你甚至不知道自己今天是在前进还是在绕圈。</p><h2 id="评测的三个层次" tabindex="-1">评测的三个层次 <a class="header-anchor" href="#评测的三个层次" aria-label="Permalink to &quot;评测的三个层次&quot;">​</a></h2><p>把&quot;评测&quot;一词拆开，Agent 场景下至少有三个层次，各自回答不同的问题，工具与指标完全不同。</p><h3 id="单元级-单工具调用对不对" tabindex="-1">单元级：单工具调用对不对 <a class="header-anchor" href="#单元级-单工具调用对不对" aria-label="Permalink to &quot;单元级：单工具调用对不对&quot;">​</a></h3><p>最低层评测的对象是<strong>单次工具调用</strong>：给定上下文，模型选对工具了吗？参数填对了吗？典型用例：</p><ul><li>用户说&quot;帮我把 src 目录下所有 ts 文件重命名为 tsx&quot;，期望 Agent 调用 <code>Bash</code> 且命令正确，而不是对每个文件手动调用 30 次 <code>Write</code>；</li><li>读文件前是否先调用了正确的路径（而不是猜路径）；</li><li>结构化输出场景下 JSON 是否合法、枚举值是否在允许范围内。</li></ul><p>这一层可以用传统单元测试的思路跑：固定输入、断言工具名与参数。它跑得快、定位准，适合在 prompt 或工具 schema 每次改动后全量执行，充当&quot;冒烟测试&quot;。</p><h3 id="任务级-端到端能不能成" tabindex="-1">任务级：端到端能不能成 <a class="header-anchor" href="#任务级-端到端能不能成" aria-label="Permalink to &quot;任务级：端到端能不能成&quot;">​</a></h3><p>单元对不等于任务成。任务级评测的对象是<strong>完整的多轮执行轨迹</strong>：给 Agent 一个目标，让它自主执行到结束，判定最终结果是否达成。代表就是 SWE-bench：给一个真实 GitHub issue 和对应仓库，Agent 产出 patch，用仓库自带的测试用例判定 pass/fail——<strong>判定标准客观、可自动执行</strong>，这是任务级评测设计的黄金标准。</p><p>任务级的核心指标是<strong>成功率</strong>（pass rate），以及由它衍生的 pass@k、pass^k（下文详述）。设计自己的任务级 eval set 时，最重要的原则是&quot;结果可判定&quot;：要么有可运行的测试，要么有可校验的产物（文件 diff、结构化数据、确定性的文本匹配），尽量避免&quot;人工看一眼&quot;这种不可复现的判定。</p><h3 id="系统级-变的到底是不是好事" tabindex="-1">系统级：变的到底是不是好事 <a class="header-anchor" href="#系统级-变的到底是不是好事" aria-label="Permalink to &quot;系统级：变的到底是不是好事&quot;">​</a></h3><p>前两层都只看&quot;对不对&quot;，系统级评测看<strong>代价与风险</strong>：</p><ul><li><strong>成本回归</strong>：这次 prompt 改动让平均 token 消耗涨了 40%，成功率只涨 2 个点，划算吗？</li><li><strong>延迟回归</strong>：新增了一轮&quot;先反思再执行&quot;，P95 延迟翻倍；</li><li><strong>安全回归</strong>：新 prompt 是否让 Agent 更容易执行危险命令、更容易泄露上下文？沙箱拒绝率的变化也是指标。</li></ul><p>很多&quot;成功率提升&quot;的改动，在系统级视角下是净亏损。成熟的团队会把成本、延迟、拒绝率与成功率放在同一个 dashboard 上，任何变更四项一起看。</p>',18)),(l(),e(r,null,{default:s((()=>[i(E,{id:"mermaid-82",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%8F%98%E6%9B%B4%3A%20prompt%20%2F%20%E6%A8%A1%E5%9E%8B%20%2F%20%E5%B7%A5%E5%85%B7%5D%20--%3E%20B%5B%E5%8D%95%E5%85%83%E7%BA%A7%E8%AF%84%E6%B5%8B%3Cbr%2F%3E%E5%B7%A5%E5%85%B7%E9%80%89%E6%8B%A9%E4%B8%8E%E5%8F%82%E6%95%B0%E6%96%AD%E8%A8%80%5D%0A%20%20%20%20A%20--%3E%20C%5B%E4%BB%BB%E5%8A%A1%E7%BA%A7%E8%AF%84%E6%B5%8B%3Cbr%2F%3E%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%88%90%E5%8A%9F%E7%8E%87%20pass%40k%5D%0A%20%20%20%20A%20--%3E%20D%5B%E7%B3%BB%E7%BB%9F%E7%BA%A7%E8%AF%84%E6%B5%8B%3Cbr%2F%3E%E6%88%90%E6%9C%AC%20%2F%20%E5%BB%B6%E8%BF%9F%20%2F%20%E5%AE%89%E5%85%A8%5D%0A%20%20%20%20B%20--%3E%20E%7B%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%3F%7D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%7C%E6%98%AF%7C%20F%5B%E5%90%88%E5%B9%B6%E5%8F%91%E5%B8%83%5D%0A%20%20%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5B%E5%AE%9A%E4%BD%8D%E5%9B%9E%E9%80%80%E5%8E%9F%E5%9B%A0%5D%0A%20%20%20%20G%20--%3E%20A%0A"})])),fallback:s((()=>u[0]||(u[0]=[g(" Loading... ")]))),_:1})),u[2]||(u[2]=o('<h2 id="构建自己的-eval-set-从失败案例出发" tabindex="-1">构建自己的 eval set：从失败案例出发 <a class="header-anchor" href="#构建自己的-eval-set-从失败案例出发" aria-label="Permalink to &quot;构建自己的 eval set：从失败案例出发&quot;">​</a></h2><p>通用 benchmark（SWE-bench、GAIA、WebArena）适合横向比较模型与产品定位，但<strong>无法回答&quot;我的用户遇到的坑，我的 Agent 处理得怎么样&quot;</strong>。自建 eval set 才是日常开发的主战场，而它的第一手素材来源是：真实失败案例。</p><h3 id="从投诉到用例" tabindex="-1">从投诉到用例 <a class="header-anchor" href="#从投诉到用例" aria-label="Permalink to &quot;从投诉到用例&quot;">​</a></h3><p>流程是这样的：</p><ol><li><strong>收集失败</strong>：用户投诉、人工抽检发现的坏 case、客服记录、内部 dogfood 里的翻车记录，全部归档。每条记录尽量保留完整上下文（用户原始请求、Agent 的完整轨迹、当时的模型与 prompt 版本）。</li><li><strong>归因分类</strong>：失败是因为工具选错？参数错？上下文缺失？还是任务本身超出当前能力？分类决定这条用例修复的希望大小。</li><li><strong>转化为测试用例</strong>：把失败场景改写成 eval 条目——输入（含必要的初始环境，如仓库快照）、预期行为或预期产物、判定方法。注意<strong>保留失败案例的真实分布</strong>：如果 60% 的投诉来自长上下文多轮场景，eval set 里长上下文用例就该占 60%，而不是凭兴趣写成十个都像 demo 的短用例。</li><li><strong>定期再生产</strong>：eval set 不是一次性的。每周把新失败案例转成用例，同时剔除被新能力覆盖后失去区分度的旧用例（但仍建议保留，用于回归）。</li></ol><h3 id="样本量-10-20-个是底线-不是目标" tabindex="-1">样本量：10-20 个是底线，不是目标 <a class="header-anchor" href="#样本量-10-20-个是底线-不是目标" aria-label="Permalink to &quot;样本量：10-20 个是底线，不是目标&quot;">​</a></h3><p>多少用例才够？给出一个可以拍脑袋使用的经验法则：<strong>10-20 个用例是能看出信号的最低限度，50-100 个才能做较细粒度的对比</strong>。</p><p>算一笔账就明白为什么。设成功率为 p，n 个用例的实验中，成功率估计的标准误是 <code>sqrt(p(1-p)/n)</code>。p=0.6、n=20 时标准误约 11 个百分点——你要在两个版本之间看到超出 ±11% 的差异，才勉强谈得上显著；n=5 时标准误约 22%，<strong>任何&quot;5 个用例提升 20%&quot;的结论都没有统计意义</strong>。这不是说小 eval set 没用——它至少能抓住&quot;彻底坏了&quot;级别的回归——而是要诚实地知道它的分辨率。</p><p>提高分辨率的另一个手段不是加用例数，而是<strong>同一用例重复 N 次</strong>（下节展开），两者按成本组合使用。</p><h3 id="eval-set-工程化的基本要求" tabindex="-1">eval set 工程化的基本要求 <a class="header-anchor" href="#eval-set-工程化的基本要求" aria-label="Permalink to &quot;eval set 工程化的基本要求&quot;">​</a></h3><ul><li><strong>版本化</strong>：eval set 进 git，每次修改有记录、可回滚，否则评测结果跨版本不可比；</li><li><strong>可复现</strong>：每条用例自带环境准备脚本（初始化沙箱、checkout 指定 commit、清理产物），做到&quot;任何人任何机器跑出同样的轨迹&quot;；</li><li><strong>判定代码化</strong>：judge 逻辑写成代码入库，同样受版本控制。</li></ul><h2 id="llm-as-judge-好用-但偏差必须管" tabindex="-1">LLM-as-judge：好用，但偏差必须管 <a class="header-anchor" href="#llm-as-judge-好用-但偏差必须管" aria-label="Permalink to &quot;LLM-as-judge：好用，但偏差必须管&quot;">​</a></h2><p>很多任务没有客观判定标准（&quot;回答是否有帮助&quot;），只能请一个更强的 LLM 来当裁判。LLM-as-judge 实用且可规模化，但<strong>裁判自身也有系统性偏差</strong>，不处理就会把评测带偏。</p><h3 id="三大偏差" tabindex="-1">三大偏差 <a class="header-anchor" href="#三大偏差" aria-label="Permalink to &quot;三大偏差&quot;">​</a></h3><p><strong>位置偏差（position bias）</strong>：成对比较（A vs B，哪个更好）时，LLM 对选项顺序敏感，倾向于偏向某个位置（常见是先出现的那个）。同一个回答放 A 位和 B 位可能得到相反的判罚。</p><p><strong>长度偏差（verbosity bias）</strong>：裁判偏爱更长、更面面俱到的回答——即使长的那份其实啰嗦、甚至包含冗余错误。对 Agent 场景尤其致命：Agent 输出天然冗长（工具调用轨迹、解释文字），长度偏差会系统性地奖励&quot;话多&quot;的版本。</p><p><strong>自我偏好（self-preference bias）</strong>：如果裁判模型和被评模型同源（比如用 GPT-5 当裁判评 GPT-5 与 Claude 的输出），裁判会偏好自己家族的风格。用同一个模型评&quot;新旧 prompt&quot;时，这个偏差同样存在。</p><h3 id="缓解手段" tabindex="-1">缓解手段 <a class="header-anchor" href="#缓解手段" aria-label="Permalink to &quot;缓解手段&quot;">​</a></h3><p>三条实践，成本不高，收益显著：</p><ol><li><strong>成对比较 + 位置随机化</strong>：不要让 judge 打绝对分（1-10 分的绝对打分跨版本漂移严重），而是让它做 A/B 成对比较；每次比较随机交换两个候选的位置，跑两次，两次结论一致才计票。这几乎消除位置偏差，同时把绝对分数的漂移问题一并解决。</li><li><strong>多 judge 投票</strong>：用两三个不同家族的模型当裁判，多数决。单 judge 的风格偏差被稀释；成本允许时这是最有效的一招。</li><li><strong>校准人类锚点</strong>：抽样一部分用例做人工评判，与 judge 结论对齐，计算一致率。一致率持续偏低说明 judge prompt 有问题或偏差未消除，需要修 judge 而不是信它。另可参考 MT-Bench 等论文中&quot;与人类一致率&quot;的报告方式，给 judge 结论一个可信度标注。</li></ol><h2 id="多轮重复、pass-k-与-pass-k" tabindex="-1">多轮重复、pass@k 与 pass^k <a class="header-anchor" href="#多轮重复、pass-k-与-pass-k" aria-label="Permalink to &quot;多轮重复、pass@k 与 pass^k&quot;">​</a></h2><p>Agent 任务的方差远大于普通问答：同一个任务，模型可能这次走对了路径、下次卡在某个工具报错上。因此 Agent 评测必须显式处理重复实验。</p><p><strong>同用例跑 N 次</strong>是基本操作：对每个用例跑 N 次（常见 5-10 次），以成功次数的比率作为该用例的成功率估计。N 的选择取决于方差：如果某用例成功率长期是 0 或 1，跑 3 次即可；如果是 0.5 附近的&quot;摇摆用例&quot;，它是版本对比的主要信息来源，值得多跑。样本预算有限时，优先给摇摆用例分配重复次数。</p><p>然后是两个容易混淆的指标，源自 OpenAI 人类评估论文（HumanEval）的定义，在 Agent 语境下含义有微妙但重要的差别：</p><ul><li><strong>pass@k</strong>：每个任务<strong>独立采样 k 次</strong>，只要有一次成功就算过。它衡量&quot;给 Agent k 次机会能否解决&quot;，对应产品里&quot;失败后自动重试&quot;的体验。数学上，pass@k = 1 - C(n-c, k)/C(n, k)（n 次采样中 c 次成功的无偏估计）。</li><li><strong>pass^k</strong>：同一任务<strong>连续执行 k 次，要求 k 次全部成功</strong>。它衡量稳定性，对应&quot;这个 Agent 能不能放进自动化流水线无人值守地跑&quot;。pass^k 对方差极度敏感——一个平均成功率 90% 的 Agent，pass^5 只剩约 59%。</li></ul><p>两者一个偏乐观、一个偏悲观，回答完全不同的产品问题。汇报评测结果时必须写清楚是哪一个，只报 pass@k 而产品实际是无人值守场景，是常见的自欺。</p><h2 id="回归防御-任何变更都跑全量-eval" tabindex="-1">回归防御：任何变更都跑全量 eval <a class="header-anchor" href="#回归防御-任何变更都跑全量-eval" aria-label="Permalink to &quot;回归防御：任何变更都跑全量 eval&quot;">​</a></h2><p>Agent 系统的组件耦合度远超传统软件：<strong>模型、prompt、工具定义、工具实现、上下文组装策略，任何一处变更都可能波及全系统的行为</strong>。换一个模型版本，之前调好的 few-shot 可能失效；改一个工具的参数描述，模型对另一个工具的调用习惯也可能变化。</p><p>所以回归纪律必须是一条硬规则：<strong>模型、prompt、工具三者中任何一个变更，都触发全量 eval 流水线</strong>。没有跑全量 eval 的变更不允许合入——把 eval 当成 CI 里的必过检查，而不是开发者心情好才跑的脚本。</p><p>配套的工程细节：</p><ul><li><strong>主记录（golden file）与告警</strong>：每个版本的全量 eval 结果落库，与上一版本逐用例 diff；任何一个用例从&quot;稳定通过&quot;变成&quot;稳定失败&quot;都要人工确认原因，杜绝&quot;整体成功率没掉但悄悄换了失败模式&quot;的隐性回归。</li><li><strong>快速与全量分层</strong>：全量 eval 贵且慢，可以设一套 5 分钟内的快速子集（易失败的摇摆用例优先）在每次提交触发，完整全量在合并前与每日定时触发。</li><li><strong>失败可回放</strong>：记录每次评测运行的完整轨迹（prompt、工具调用、结果），失败用例能一键重放，这会把 eval 从&quot;分数报表&quot;升级为&quot;调试工具&quot;。</li></ul><h2 id="评测环境隔离与数据污染" tabindex="-1">评测环境隔离与数据污染 <a class="header-anchor" href="#评测环境隔离与数据污染" aria-label="Permalink to &quot;评测环境隔离与数据污染&quot;">​</a></h2><p>最后是被讨论得最少、却最容易毁掉评测可信度的两个问题。</p><p><strong>数据污染（contamination）</strong>：如果 eval 用例的内容已经在模型的训练数据里（SWE-bench 的 issue 不少是公开仓库的真实 issue，各家模型大概率见过），评测测的是记忆而不是能力。缓解手段：优先使用私有失败案例构建 eval set（天然无污染）；对公开 benchmark，关注其更新版本（SWE-bench Verified、LiveBench 类&quot;滚动更新&quot;榜单）；用例中的标识符、变量名可做改写以降低记忆命中。反过来也要注意<strong>不要</strong>故意用训练时点之后的全新数据做高难度评测，否则可能测出的是模型&quot;瞎蒙能力&quot;。</p><p><strong>评测环境隔离</strong>：评测必须在受控沙箱内运行（这正是前一篇沙箱文章的价值所在）——网络按需白名单、文件系统隔离、每条用例独立环境。否则上一条用例留下的副作用会污染下一条（比如 Agent 发现了一个&quot;作弊路径&quot;写进了缓存，后续所有用例&quot;成功&quot;都是假象）。同时隔离保证安全：eval 中故意包含攻击性输入（注入用例、危险命令用例）时，绝不能在无隔离的开发机上跑。</p><h2 id="工具链推荐" tabindex="-1">工具链推荐 <a class="header-anchor" href="#工具链推荐" aria-label="Permalink to &quot;工具链推荐&quot;">​</a></h2><p>按团队投入程度分三档：</p><ul><li><strong>promptfoo</strong>：轻量开源的 prompt/Agent 评测框架，YAML 声明用例，支持多 provider 对比、LLM-as-judge（内置成对比较）、断言式判定。适合起步阶段，半天就能接入 CI。</li><li><strong>LangSmith（及 Langfuse 类平台）</strong>：评测 + 轨迹追踪 + 数据集管理一体的商业平台，优点是轨迹可视化、失败分析体验好、与 LLM 应用框架集成顺滑；代价是数据出内网（Langfuse 可自部署）与供应商锁定。</li><li><strong>自建 harness</strong>：当评测需求长出团队特异性——私有判定逻辑、特殊环境准备、成本审计口径——自建就是必然。核心组件不过五件：用例存储（git 里的 YAML/JSON）、 runner（并发调度 + 沙箱调用）、judge（代码判定 + LLM 裁判）、结果库（带版本与 diff）、报告（dashboard）。自建的最大好处是评测逻辑与业务强绑定，长期维护成本反而更低。</li></ul><p>起步建议：先用 promptfoo 把&quot;全量回归&quot;这条纪律立起来，等评测成为日常流程后，再按需迁移到平台或自建。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>Agent 工程与传统软件工程最深的分野在于：<strong>它的行为是非确定的，而它的开发节奏又是极快的</strong>。非确定要求统计判断，快节奏要求自动化护栏，两者共同指向同一件事——把 evals 建成开发流程的地基，而不是事后验证。从今天起把用户的每个投诉变成 eval 用例，把每次变更绑上全量回归，一个月后你会第一次真正&quot;看见&quot;自己的 Agent 在变好还是变坏。</p>',41))])}]]);export{u as __pageData,p as default};
